CREATE TABLE user_profiles (user_id uuid PRIMARY KEY, role text NOT NULL CHECK (role IN ('patient', 'provider', 'admin')), display_name text NOT NULL, tz text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patient_records (id uuid PRIMARY KEY, patient_ref text NOT NULL UNIQUE, dob date NOT NULL, full_name text NOT NULL, claimed_by uuid UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz);
CREATE TABLE verification_attempts (id uuid PRIMARY KEY, account_id uuid NOT NULL, network_hmac text NOT NULL, patient_ref_hmac text NOT NULL, result text NOT NULL CHECK (result IN ('allowed', 'denied', 'locked')), attempted_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_attempts_account_attempted_idx ON verification_attempts (account_id, attempted_at DESC);
CREATE INDEX verification_attempts_network_attempted_idx ON verification_attempts (network_hmac, attempted_at DESC);
CREATE INDEX verification_attempts_reference_attempted_idx ON verification_attempts (patient_ref_hmac, attempted_at DESC);
CREATE TABLE patient_claim_events (id uuid PRIMARY KEY, patient_record_id uuid NOT NULL REFERENCES patient_records(id) ON DELETE RESTRICT, actor_user_id uuid NOT NULL, event_type text NOT NULL CHECK (event_type IN ('claim', 'unlink', 'recovery')), occurred_at timestamptz NOT NULL DEFAULT now(), reason_code text);
CREATE INDEX patient_claim_events_record_occurred_idx ON patient_claim_events (patient_record_id, occurred_at DESC);
CREATE TABLE providers (id uuid PRIMARY KEY, user_id uuid NOT NULL UNIQUE, tz text NOT NULL, slot_length_min integer NOT NULL CHECK (slot_length_min BETWEEN 5 AND 480), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE services (id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (provider_id, name));
CREATE INDEX services_provider_active_idx ON services (provider_id) WHERE active;
CREATE TABLE availability_rules (id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6), local_start time NOT NULL, local_end time NOT NULL, effective_from date NOT NULL, effective_until date, CHECK (local_end > local_start), CHECK (effective_until IS NULL OR effective_until >= effective_from));
CREATE TABLE blocked_times (id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, blocked_range tstzrange NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (NOT isempty(blocked_range)));
CREATE INDEX blocked_times_range_idx ON blocked_times USING gist (blocked_range);
CREATE INDEX blocked_times_provider_idx ON blocked_times (provider_id);
CREATE TABLE slots (id uuid PRIMARY KEY, provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('open', 'booked', 'blocked')), created_at timestamptz NOT NULL DEFAULT now(), CHECK (end_at > start_at), UNIQUE (provider_id, start_at));
CREATE INDEX slots_provider_open_start_idx ON slots (provider_id, start_at) WHERE status = 'open';
CREATE TABLE appointments (id uuid PRIMARY KEY, slot_id uuid NOT NULL REFERENCES slots(id) ON DELETE RESTRICT, patient_user_id uuid NOT NULL, provider_id uuid NOT NULL REFERENCES providers(id) ON DELETE RESTRICT, service_id uuid NOT NULL REFERENCES services(id) ON DELETE RESTRICT, start_at timestamptz NOT NULL, schedule_version integer NOT NULL DEFAULT 1 CHECK (schedule_version >= 1), status text NOT NULL CHECK (status IN ('requested', 'confirmed', 'completed', 'cancelled', 'no-show')), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (patient_user_id, idempotency_key));
CREATE UNIQUE INDEX appointments_active_provider_start_unique ON appointments (provider_id, start_at) WHERE status <> 'cancelled';
CREATE UNIQUE INDEX appointments_active_slot_unique ON appointments (slot_id) WHERE status <> 'cancelled';
CREATE INDEX appointments_patient_start_idx ON appointments (patient_user_id, start_at DESC);
CREATE TABLE appointment_events (id uuid PRIMARY KEY, appointment_id uuid NOT NULL REFERENCES appointments(id) ON DELETE RESTRICT, from_status text CHECK (from_status IN ('requested', 'confirmed', 'completed', 'cancelled', 'no-show')), to_status text NOT NULL CHECK (to_status IN ('requested', 'confirmed', 'completed', 'cancelled', 'no-show')), actor_user_id uuid, actor_role text NOT NULL CHECK (actor_role IN ('patient', 'provider', 'admin', 'system')), occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX appointment_events_appointment_occurred_idx ON appointment_events (appointment_id, occurred_at);
CREATE TABLE studies (id uuid PRIMARY KEY, patient_record_id uuid NOT NULL REFERENCES patient_records(id) ON DELETE RESTRICT, appointment_id uuid REFERENCES appointments(id) ON DELETE RESTRICT, performed_at timestamptz, visit_status text NOT NULL CHECK (visit_status IN ('completed', 'scheduled', 'cancelled')), description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (visit_status <> 'completed' OR performed_at IS NOT NULL));
CREATE INDEX studies_patient_completed_idx ON studies (patient_record_id, performed_at DESC) WHERE visit_status = 'completed';
CREATE TABLE images (id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES studies(id) ON DELETE RESTRICT, storage_path text NOT NULL UNIQUE, thumbnail_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cine_clips (id uuid PRIMARY KEY, study_id uuid NOT NULL REFERENCES studies(id) ON DELETE RESTRICT, storage_path text NOT NULL UNIQUE, frame_count integer NOT NULL CHECK (frame_count > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY, patient_record_id uuid NOT NULL REFERENCES patient_records(id) ON DELETE RESTRICT, study_id uuid NOT NULL REFERENCES studies(id) ON DELETE RESTRICT, status text NOT NULL CHECK (status IN ('preliminary', 'signed')), signed_at timestamptz, signed_by uuid, storage_path text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), CHECK ((status = 'signed' AND signed_at IS NOT NULL AND signed_by IS NOT NULL) OR (status = 'preliminary' AND signed_at IS NULL AND signed_by IS NULL)));
CREATE INDEX reports_patient_signed_idx ON reports (patient_record_id) WHERE status = 'signed';
CREATE TABLE share_links (id uuid PRIMARY KEY, token_hash text NOT NULL UNIQUE, resource_type text NOT NULL CHECK (resource_type IN ('image', 'report')), resource_id uuid NOT NULL, recipient_email text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, access_count integer NOT NULL DEFAULT 0 CHECK (access_count >= 0), last_accessed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX share_links_active_resource_idx ON share_links (resource_type, resource_id) WHERE revoked_at IS NULL;
CREATE TABLE email_outbox (id uuid PRIMARY KEY, appointment_id uuid REFERENCES appointments(id) ON DELETE RESTRICT, schedule_version integer, interval text, kind text NOT NULL CHECK (kind IN ('share', 'reminder')), payload jsonb NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('pending', 'claimed', 'sent', 'failed')), attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), idempotency_key text NOT NULL UNIQUE, provider_message_id text, claimed_at timestamptz, lease_expires_at timestamptz, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((kind = 'reminder' AND appointment_id IS NOT NULL AND schedule_version >= 1 AND interval IS NOT NULL) OR (kind = 'share' AND appointment_id IS NULL AND schedule_version IS NULL AND interval IS NULL)), UNIQUE (appointment_id, schedule_version, interval));
CREATE INDEX email_outbox_due_idx ON email_outbox (due_at) WHERE status IN ('pending', 'failed');
CREATE TABLE audit_log (id uuid PRIMARY KEY, actor_reference text, actor_role text NOT NULL CHECK (actor_role IN ('patient', 'provider', 'admin', 'system', 'anonymous')), action text NOT NULL, target_type text NOT NULL, target_reference text NOT NULL, result text NOT NULL CHECK (result IN ('allowed', 'denied')), network_reference text, client_reference text, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_log_target_occurred_idx ON audit_log (target_type, target_reference, occurred_at DESC);
CREATE INDEX audit_log_actor_occurred_idx ON audit_log (actor_reference, occurred_at DESC);
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM {{APP_DB_ROLE}};
GRANT USAGE ON SCHEMA public TO {{APP_DB_ROLE}};
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO {{APP_DB_ROLE}};
REVOKE ALL ON schema_migrations FROM {{APP_DB_ROLE}};
REVOKE UPDATE, DELETE ON audit_log FROM {{APP_DB_ROLE}};
